import{_ as a,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"德里克·莫恩","description":"","frontmatter":{"title":"德里克·莫恩","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/德里克·莫恩.md","filePath":"04_people/德里克·莫恩.md"}'),o={name:"04_people/德里克·莫恩.md"};function i(s,e,n,_,h,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="德里克·莫恩-derek-mau" tabindex="-1">德里克·莫恩（Derek Mau） <a class="header-anchor" href="#德里克·莫恩-derek-mau" aria-label="Permalink to &quot;德里克·莫恩（Derek Mau）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：所罗门兄弟投资银行负责人</li><li><strong>与巴菲特关系</strong>：巴菲特收购所罗门兄弟后的核心管理层成员</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>德里克·莫恩在所罗门兄弟公司担任投资银行部门负责人，是巴菲特接管所罗门后倚重的关键人物之一。1991年，所罗门兄弟因交易员约翰·梅里韦瑟违规炒作美国国债而陷入空前危机，公司面临被吊销国债交易资格的严峻局面，可能导致破产边缘。在此危急时刻，巴菲特以&quot;救火队长&quot;身份介入，莫恩成为协助稳定公司运营的核心高管之一。</p><p>巴菲特在深入调查后发现，所罗门的问题根源在于内部监管失效和风控体系存在严重漏洞，而并非整个公司管理层的问题。莫恩在此后的公司重建过程中发挥了重要作用，帮助所罗门逐步恢复市场信誉和业务正常运转。他的务实态度和专业能力得到了巴菲特的认可，在巴菲特主导的重组和改革中承担了关键执行角色。</p><p>所罗门兄弟危机最终以与美国财政部的和解告终，公司得以继续运营。巴菲特在此事件中展现了危机处理的能力，也借此机会在公司内部推行了一系列治理改革。莫恩作为管理层代表，在配合巴菲特完成整改和重建方面发挥了积极作用。此后所罗门逐步回归正轨，最终成为伯克希尔的全资子公司。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：所罗门兄弟国债丑闻爆发，莫恩在公司危机中承担管理职责</li><li><strong>1992年</strong>：协助巴菲特完成所罗门内部整改与监管和解</li><li><strong>1993年后</strong>：参与所罗门并入伯克希尔的整合工作</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=德里克·莫恩在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=德里克·莫恩在1992年股东信中的原话">1992年：完整翻译|/01_letters/1992年/翻译</a></li></ul>',11)])])}const c=a(o,[["render",i]]);export{u as __pageData,c as default};
